-- Read-only catalog packet for the six-migration candidate. No customer rows.
-- Execute only through authorized access to the confirmed Vacancy project.
-- Snapshot queries do not apply migrations, invoke bootstrap or alter roles.


select jsonb_build_object(
'observed_at',now(),
'database_version',current_setting('server_version'),
'tables',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'owner',pg_get_userbyid(c.relowner)) order by n.nspname,c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private') and c.relkind in ('r','p') and c.relname in ('profiles','admin_users','admin_moderation_log','vacancies','properties','rooms','listing_activity_log','admin_access_roles','admin_change_audit','admin_appearance_current','admin_appearance_drafts','admin_appearance_revisions')),
'columns',(select jsonb_agg(jsonb_build_object('schema',table_schema,'table',table_name,'name',column_name,'type',udt_name,'nullable',is_nullable,'default',column_default) order by table_schema,table_name,ordinal_position) from information_schema.columns where (table_schema='public' and table_name in ('admin_users','admin_moderation_log','listing_activity_log','admin_access_roles','admin_change_audit','admin_appearance_current','admin_appearance_drafts','admin_appearance_revisions')) or (table_schema='public' and table_name='profiles' and column_name in ('id','account_status')) or (table_schema='auth' and table_name='users' and column_name in ('id','email','email_confirmed_at','deleted_at','is_anonymous','banned_until'))),
'constraints',(select jsonb_agg(jsonb_build_object('table',conrelid::regclass::text,'name',conname,'definition',pg_get_constraintdef(oid)) order by conrelid::regclass::text,conname) from pg_constraint where conrelid in (select c.oid from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('admin_users','admin_moderation_log','profiles','vacancies','listing_activity_log','admin_access_roles','admin_change_audit','admin_appearance_current','admin_appearance_drafts','admin_appearance_revisions'))),
'policies',(select jsonb_agg(to_jsonb(p) order by tablename,policyname) from pg_policies p where schemaname='public' and tablename in ('profiles','admin_users','vacancies','admin_moderation_log','listing_activity_log','admin_access_roles','admin_change_audit','admin_appearance_current','admin_appearance_drafts','admin_appearance_revisions')),
'triggers',(select jsonb_agg(jsonb_build_object('table',tgrelid::regclass::text,'name',tgname,'enabled',tgenabled,'definition',pg_get_triggerdef(oid)) order by tgrelid::regclass::text,tgname) from pg_trigger where not tgisinternal and tgrelid in (select c.oid from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('profiles','admin_users','vacancies','listing_activity_log','admin_change_audit','admin_appearance_revisions','admin_appearance_drafts'))),
'table_grants',(select jsonb_agg(to_jsonb(g) order by table_name,grantee,privilege_type) from information_schema.table_privileges g where table_schema='public' and table_name in ('profiles','admin_users','admin_moderation_log','vacancies','listing_activity_log','admin_access_roles','admin_change_audit','admin_appearance_current','admin_appearance_drafts','admin_appearance_revisions') and grantee in ('PUBLIC','anon','authenticated','service_role')),
'column_grants',(select jsonb_agg(to_jsonb(g) order by table_name,column_name,grantee,privilege_type) from information_schema.column_privileges g where table_schema='public' and table_name in ('profiles','admin_users','vacancies') and grantee in ('anon','authenticated') and privilege_type='UPDATE'),
'migrations',(select jsonb_agg(jsonb_build_object('version',version,'name',name) order by version) from supabase_migrations.schema_migrations)
) as catalog;


select n.nspname as schema,p.proname as name,pg_get_function_identity_arguments(p.oid) as args,pg_get_function_result(p.oid) as returns,p.prosecdef as security_definer,p.provolatile as volatility,p.proconfig as settings,pg_get_userbyid(p.proowner) as owner,p.proacl::text as acl,pg_get_functiondef(p.oid) as definition from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('private','public') and p.proname in ('is_admin','is_active_user','is_permanent_user','vacancy_room_owned_by','record_listing_activity','admin_set_vacancy_status','admin_deactivate_vacancy','admin_set_user_status','admin_resolve_report','reject_admin_audit_rewrite','admin_can','admin_my_capabilities','admin_access_roles_read','admin_set_access_role','admin_change_audit_recent','protect_last_admin_owner_status','audit_admin_appearance_draft','validate_appearance_config','admin_appearance_state','admin_appearance_save_draft','admin_appearance_history','admin_appearance_publish','admin_appearance_restore_draft','site_appearance_published','bootstrap_first_admin_owner') order by n.nspname,p.proname,args;

select jsonb_build_object(
'observed_at',now(),
'schema_acl',(select jsonb_agg(jsonb_build_object('name',nspname,'acl',nspacl::text)) from pg_namespace where nspname in ('private','public','auth')),
'indexes',(select jsonb_agg(jsonb_build_object('table',tablename,'name',indexname,'definition',indexdef) order by tablename,indexname) from pg_indexes where schemaname='public' and tablename in ('listing_activity_log','admin_users','admin_moderation_log')),
'activity_triggers',(select jsonb_agg(jsonb_build_object('table',tgrelid::regclass::text,'name',tgname,'enabled',tgenabled,'definition',pg_get_triggerdef(oid)) order by tgrelid::regclass::text,tgname) from pg_trigger where not tgisinternal and tgrelid in ('public.properties'::regclass,'public.rooms'::regclass,'public.vacancies'::regclass)),
'defaults',(select jsonb_agg(jsonb_build_object('owner',pg_get_userbyid(d.defaclrole),'schema',coalesce(n.nspname,'ALL'),'type',d.defaclobjtype,'acl',d.defaclacl::text)) from pg_default_acl d left join pg_namespace n on n.oid=d.defaclnamespace where n.nspname in ('public','private') or d.defaclnamespace=0),
'missing_source_migration',(select jsonb_agg(jsonb_build_object('version',version,'name',name,'statement_count',array_length(statements,1),'statements_md5',md5(statements::text))) from supabase_migrations.schema_migrations where name='listing_activity_log')
) details;
